# name: set_level_yes_rate_dispersion
# description: Standard deviation across example sets (with 40+ rows) of each set's overall yes-rate; observed > null means people differentiate sets (some sets read as broad, others as narrow) more than the model does, observed < null means the model over-differentiates.
def test_statistic(df):
    y = df["rating"].astype(float)
    g = y.groupby(df["number_set"].astype(str)).agg(["mean", "size"])
    g = g[g["size"] >= 40]
    if len(g) < 2:
        return 0.0
    return float(g["mean"].std())

# name: early_session_flatness
# description: Yes-rate on trials 50-99 minus trials 0-49; observed < null means the criterion does not relax at all during the first ~100 trials (a delayed, step-like shift) whereas the model's saturating exponential relaxation predicts the steepest rise right at the start.
def test_statistic(df):
    ti = df["trial_index"].astype(float).to_numpy()
    y = df["rating"].astype(float).to_numpy()
    a = (ti >= 50) & (ti < 100)
    b = ti < 50
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(y[a].mean() - y[b].mean())
